head.script:
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.__isBackground = function() {
    var color = WebSquare.wUnit.getJq("#wq_uuid_9_cell_1_2").css("background-color");
    if (color.indexOf("rgb") < 0) {
        return color != "rgb(252, 167, 60)";
    }
    return color == "rgb(252, 167, 60)";
}
scwin.setVal = function() {
    scwin.dbClick('wq_uuid_9_cell_0_2');
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#wq_uuid_9_cell_0_2').simulate('key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 브라우저에서 name3 에 컬럼을 더블클릭 후 'qong1243@sss.com' 을 입력 후 엔터키를 누른다.
    //1. Double-click on the column name3 in your browser, type 'qong1243@sss.com' and press Enter.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_wq_uuid_9___autoComplete_0_col3_col3_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_wq_uuid_9___autoComplete_0_col3_col3_itemTable_1').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_9_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 'qong1243@sss.com' 데이터가 입력 후 다음 컬럼으로 Focus 이동된다. 
    // 1. After inputting 'qong1243@sss.com' data, focus is moved to the next column.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_9_cell_0_2').innerText", "qong1243@sss.com");
    WebSquare.wUnit.addCommand("assert", "scwin.__isBackground()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 16-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
